/**
 * trendCodeMap.ts — canonical display-code ↔ trend-ID mapping.
 *
 * GENERATED by scripts/generate_seed_from_core_set.py from the same JSON
 * as pulse/seed_trends.py (September 2026 core set, release 2.11.0).
 * Single source of truth for the short trend codes used across the
 * Consumer Journey layer:
 *   code  = force letter (C/T/G/K/E/X) + the rNN number of the seed trend id
 *   e.g.  'C-01' ↔ consumer_r01, 'X-15' ↔ competitive_r15.
 * Names/forces/directions are verbatim from the seed — do NOT hand-edit;
 * regenerate when the trend base changes.
 *
 * RETIRED_CODES: display codes whose trends left the base. Since the
 * September 2026 review each entry says what happened to the code:
 *   mergedInto  the driver(s) that carry its content now (merge,
 *               substitution or force move) — evidence cards resolve
 *               through it to the live driver;
 *   residueIn   a deleted driver whose one fact or watch note lives
 *               inside another driver (still retired, no live link);
 *   neither     deleted outright (watch list) with the review's reason.
 */

export type TrendDirection = 'Expansion' | 'Contraction';

export interface TrendCodeInfo {
  trendId: string;
  name: string;
  force: string;
  direction: TrendDirection;
  /** First sentence of the seed description — offline fallback only;
   *  the live description should come from the trends API. */
  fallbackDescription: string;
}

export interface RetiredCodeInfo {
  /** Name the code carried in the base it was retired from. */
  name: string;
  /** One-line reason from the review that retired it. */
  note: string;
  /** Base version that retired the code. */
  retiredIn: 'v3.1' | 'v3.3' | 'v3.11';
  /** Live code(s) that carry this driver's content now. */
  mergedInto?: string[];
  /** Live code(s) that keep a fact or watch note from this deleted driver. */
  residueIn?: string[];
}

