const ID_TO_CODE: Record<string, string> = Object.fromEntries(
  Object.entries(TREND_CODE_MAP).map(([code, v]) => [v.trendId, code]),
);

export const trendIdForCode = (code: string): string | undefined => TREND_CODE_MAP[code]?.trendId;
export const codeForTrendId = (trendId: string): string | undefined => ID_TO_CODE[trendId];

/** The live code a citation resolves to: itself when live, the first
 *  merged-into target when the code was absorbed, undefined when the
 *  driver was deleted (a residue note is not a live driver). */
export const liveCodeFor = (code: string): string | undefined => {
  if (TREND_CODE_MAP[code]) return code;
  const target = RETIRED_CODES[code]?.mergedInto?.[0];
  return target && TREND_CODE_MAP[target] ? target : undefined;
};
